reference_css:
* { box-sizing: border-box; }
:root { color-scheme: light; --ink: #172554; --muted: #475569; --line: #d6d3d1; --surface: #fff; --accent: #1d4ed8; --space: clamp(1rem, 2vw, 1.5rem); --radius: .85rem; }
body { margin: 0; color: var(--ink); background: var(--surface); font: 1rem/1.6 system-ui, sans-serif; }
a { color: inherit; }
.announcement-bar { padding: .5rem 1rem; text-align: center; color: white; background: #172554; font-size: .85rem; }
.store-header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; padding: 1.25rem max(1rem, calc((100vw - 78rem) / 2)); border-bottom: 1px solid var(--line); }
.brand { font-weight: 900; letter-spacing: -.03em; text-decoration: none; }
.store-header nav, .category-row { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem; }
.store-header nav a, .category-row a { text-decoration: none; }
.cart-link { display: flex; gap: .5rem; align-items: center; }
.cart-link span { display: grid; place-items: center; min-width: 1.5rem; aspect-ratio: 1; border-radius: 50%; background: #dbeafe; font-size: .8rem; }
.page-shell { width: min(calc(100% - 2rem), 78rem); margin-inline: auto; }
.store-hero { display: grid; grid-template-columns: minmax(0, 1fr) minmax(14rem, .8fr); gap: var(--space); align-items: center; padding-block: clamp(3rem, 8vw, 6rem); }
.store-hero h1 { font-size: clamp(2.4rem, 6vw, 4.75rem); line-height: 1.02; max-width: 12ch; letter-spacing: -.04em; }
.store-hero-art { min-height: 18rem; border-radius: 1.5rem; background: linear-gradient(135deg, #f5d0a9, #dbeafe 52%, #bbf7d0); }
.eyebrow { color: var(--accent); text-transform: uppercase; letter-spacing: .12em; font-size: .76rem; font-weight: 850; }
.button { display: inline-block; border: 2px solid var(--accent); border-radius: .5rem; padding: .7rem 1rem; color: #fff; background: var(--accent); font: inherit; font-weight: 750; text-decoration: none; }
.button-secondary { background: transparent; color: var(--accent); }
.category-row { padding-block: 1rem; border-block: 1px solid var(--line); }
.category-row a { padding: .4rem .75rem; border-radius: 99px; background: #f1f5f9; }
.store-section { padding-block: 2rem 4rem; }
.section-heading { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 1rem; }
.product-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); gap: var(--space); }
.product-card { min-width: 0; padding: .75rem; border: 1px solid var(--line); border-radius: var(--radius); }
.product-art { display: grid; place-items: center; aspect-ratio: 4 / 3; border-radius: .65rem; color: #172554; font-size: 2rem; font-weight: 850; }
.art--clay { background: #fed7aa; } .art--sage { background: #d1fae5; } .art--sky { background: #dbeafe; } .art--sand { background: #fef3c7; }
.product-price { font-weight: 850; font-size: 1.1rem; }
.brand-story, .order-summary { padding: 1.5rem; margin-block: 1.5rem; border-radius: var(--radius); background: #f8fafc; }
:focus-visible { outline: 3px solid #0f766e; outline-offset: 3px; }
[data-theme="dark"] { color-scheme: dark; --ink: #e2e8f0; --muted: #cbd5e1; --line: #475569; --surface: #0f172a; --accent: #93c5fd; }
@media (max-width: 50rem) { .store-hero { grid-template-columns: 1fr; } .store-hero-art { min-height: 10rem; } }
@media print { .announcement-bar, .store-header nav, .cart-link, .category-row, .button, .product-art { display: none !important; } body { color: #000; background: #fff; } .order-summary { display: block; border: 1px solid #000; } .product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; } }
